// The legal texts the app shows (docs/legal/*.md) → apps/mobile/src/i18n/legalDocs.generated.ts,
// with their placeholders left in: the app fills them from brand.ts and legalEntity.ts, so naming
// the data controller needs no new run. `node --experimental-strip-types scripts/site/legal-docs.ts`
// from the repo root after a text changes; the test (legal-docs.test.ts) checks the generated file
// against the texts.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

// The app's document keys and the file each is (docs/legal/<slug>.md).
export const APP_LEGAL_DOCS = {
  terms: 'kullanim-kosullari',
  kvkk: 'kvkk-aydinlatma-metni',
  privacy: 'gizlilik-politikasi',
  community: 'topluluk-kurallari',
} as const;

export const LEGAL_DOCS_FILE = 'apps/mobile/src/i18n/legalDocs.generated.ts';

export function legalDocsSource(root: string): string {
  const entries = Object.entries(APP_LEGAL_DOCS).map(([key, slug]) => {
    const markdown = readFileSync(join(root, 'docs/legal', `${slug}.md`), 'utf8');
    return `  ${key}: ${JSON.stringify(markdown.replace(/\r\n/g, '\n'))},`;
  });
  const slugs = Object.entries(APP_LEGAL_DOCS).map(([key, slug]) => `  '${slug}': '${key}',`);
  return `// Generated by scripts/site/legal-docs.ts from docs/legal/*.md. Do not edit; run the script.\nexport const LEGAL_DOCS = {\n${entries.join('\n')}\n} as const;\n\nexport type LegalDocKey = keyof typeof LEGAL_DOCS;\n\n// A text's page on skall.world (its file name) → its key here.\nexport const LEGAL_DOC_BY_SLUG: Record<string, LegalDocKey | undefined> = {\n${slugs.join('\n')}\n};\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.cwd();
  writeFileSync(join(root, LEGAL_DOCS_FILE), legalDocsSource(root));
}
